// 带名字、路径等可变内容的句子。$1 $2 是原样带过去的内容；{t1} 表示把第 1 段也翻译一下。
const SIZE = "([\\d.,]+ ?[KMGT]?B)";
const patterns = [
  [/^(.+) · Pixiv Viewer$/, "$1 · Pixiv Viewer"],
  [/^在 Pixiv 打开 (.+) 的主页$/, "Open $1's profile on Pixiv"],
  [/^打开 (.+) 的画师主页$/, "Open $1's artist page"],
  [/^查看 (.+) 的全部作品$/, "See all works by $1"],
  [/^(.+) 的作品 · (\d+)$/, "Works by $1 · $2"],
  [/^(.+) · 第 (\d+) 页 · 试过 (\d+) 次$/, "$1 · page $2 · tried $3 times"],
  [/^已把 (.+) 加入“(.+)”$/, "Added $1 to “$2”"],
  [/^已把 (.+) 移出“(.+)”$/, "Removed $1 from “$2”"],
  [/^已在文件夹：(.+)。点击调整$/, "In folders: $1. Click to change"],
  [/^已新建“(.+)”并加入$/, "Created “$1” and added"],
  [/^已新建文件夹“(.+)”，在画师上点右键可以加入$/, "Created folder “$1”; right-click an artist to add"],
  [/^已删除文件夹“(.+)”（画师和图片不受影响）$/, "Deleted folder “$1” (artists and images are not affected)"],
  [/^已添加账号 (.*)$/, "Added account $1"],
  [/^已添加 (.+)$/, "Added $1"],
  [/^已移除 (.+)$/, "Removed $1"],
  [/^移除标签 (.+)$/, "Remove tag $1"],
  [/^(.+) 已经用于“(.+)”，先把那边改掉$/, "$1 is already used for “{t2}”; change that one first"],
  [/^强调色 (#[0-9a-fA-F]+)$/, "Accent color $1"],
  [/^位画师检查失败：(.+)$/, "artists failed to check: $1"],
  [/^位缺头像：(.+)。点“补全”下载。$/, "have no avatar: $1. Click Fill in to download."],
  [/^有新版本 ([\d.]+)（(.+)）$/, "Version $1 is available ($2)"],
  [/^新版本 ([\d.]+) 已经下载好$/, "Version $1 has been downloaded"],
  [/^已经是最新版本（(.+)）$/, "You have the latest version ($1)"],
  [new RegExp(`^正在下载 ${SIZE} \\/ ${SIZE}$`), "Downloading $1 / $2"],
  [/^已更新到 ([\d.]+)（之前是 (.+)）$/, "Updated to $1 (was $2)"],
  [/^已导出到 (.+)（(\d+) 个日志）$/, "Exported to $1 ($2 logs)"],
  [new RegExp(`^已清空缩略图缓存，释放 ${SIZE}$`), "Thumbnail cache cleared, $1 freed"],
  [new RegExp(`^缩略图缓存 · ${SIZE}$`), "Thumbnail cache · $1"],
  [new RegExp(`^约 ${SIZE}$`), "about $1"],
  [new RegExp(`^个文件 · 约 ${SIZE}$`), "files · about $1"],
  [new RegExp(`^个文件待下载 · 约 ${SIZE}$`), "files pending · about $1"],
  [new RegExp(`^下载现有的 ([\\d,]+) 个待下载文件（约 ${SIZE}），不检查新作品。$`), "Downloads the $1 pending files (about $2) without checking for new works."],
  [/^(\d+) 个账号 · 保存方式 (.+)$/, "$1 accounts · storage: $2"],
  [/^(\d[\d,]*) 位画师 · (\d[\d,]*) 个作品$/, "$1 artists · $2 works"],
  [/^(\d+) 个头像$/, "$1 avatars"],
  [/^(主账号|备用) · (.*)上次验证 (.+)$/, "{t1} · $2last verified $3"],
  [/^(.+) · ID (\d+) · 上次验证 (.+)$/, "$1 · ID $2 · last verified $3"],
  [/^已用 (.+) · 约剩 (.+)$/, "{t1} elapsed · about {t2} left"],
  [/^已用 (.+)$/, "{t1} elapsed"],
  [/^(\d+) 小时 (\d+) 分$/, "$1 h $2 min"], [/^(\d+) 分 (\d+) 秒$/, "$1 min $2 s"], [/^(\d+) 分钟$/, "$1 min"], [/^(\d+) 秒$/, "$1 s"],
  [/^已经 (.+) 没有新进展，仍在等待。通常是被限速、网络不通或保存位置响应慢，看下面每个账号的状态；一直不恢复的话可以停止后重新开始，进度会保留。$/, "No progress for {t1}; still waiting. Usually a rate limit, no network, or slow storage; see each account's status below. If it never recovers, stop and start again; progress is kept."],
  [/^(\d+) 秒后(关机|让电脑睡眠|让电脑休眠|退出软件)$/, "{t2} in $1 s"],
  [/^ID (\d+) · (.+)$/, "ID $1 · {t2}"],
];

